		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- Fish guide BV1Xd4y1Q72N: the missing tornado is relative north.\n-- One bounded complete snapshot, never aggregate simultaneous EntityAdd events.\nlocal now = TensorReactions_CurrentTimer\nlocal candidates = TensorCore.entityList(\"contentid=9213\")\nif type(candidates) ~= \"table\" then return end\nlocal ponds, sx, sz = {}, 0, 0\nfor _, ent in pairs(candidates) do\n    if ent and ent.pos and Argus.getEntityModel(ent.id) == 11337\n        and Argus.isEntityVisible(ent.id) then\n        local x, z = ent.pos.x - 100, ent.pos.z - 100\n        local r2 = x*x + z*z\n        if r2 >= 210 and r2 <= 240 then\n            ponds[#ponds+1] = {id=ent.id,x=x,z=z}\n            sx, sz = sx+x, sz+z\n        end\n    end\nend\nif #ponds ~= 3 then return end\nlocal length = math.sqrt(sx*sx + sz*sz)\nif length < 14.5 or length > 15.5 then return end\nlocal fx, fz = -sx/length, -sz/length\nlocal rx, rz = -fz, fx\nlocal left, right, back = false, false, false\nfor _, p in ipairs(ponds) do\n    local u, v = p.x*rx+p.z*rz, p.x*fx+p.z*fz\n    if math.abs(u+15)<0.6 and math.abs(v)<0.6 and not left then left=true\n    elseif math.abs(u-15)<0.6 and math.abs(v)<0.6 and not right then right=true\n    elseif math.abs(u)<0.6 and math.abs(v+15)<0.6 and not back then back=true\n    else return end\nend\nif not (left and right and back) then return end\nlocal hands = TensorCore.entityList(\"contentid=9212\")\nif type(hands) ~= \"table\" then return end\nlocal handID\nfor _, ent in pairs(hands) do\n    if ent and Argus.getEntityModel(ent.id) == 11336 then\n        if handID then return end\n        handID = ent.id\n    end\nend\nif not handID then return end\ndata.stringTeaP1GuideV1 = {\n    fx=fx,fz=fz,rx=rx,rz=rz,ponds=ponds,\n    roles={\"MT\",\"ST\",\"H1\",\"H2\",\"D1\",\"D2\",\"D3\",\"D4\"},\n    handID=handID,blue=false,ready=true,capturedAt=now,\n}\nself.used = true\n",
							name = "MuAi 职能联动",
							uuid = "9a965d07-73ae-5782-9a1a-2c98182cd982",
							version = 2.1,
						},
