		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- Fish guide BV1Xd4y1Q72N, first Cascade preposition only.\n-- MuAi owns both the role assignment and dynamic guide appearance.\nlocal s = data.stringTeaP1GuideV1\nif not s or not s.ready then return end\nlocal m = MuAiGuide\nif not m or type(m.Party) ~= \"table\" or type(m.GetPlayer) ~= \"function\"\n    or type(m.FrameDirect) ~= \"function\" then return end\nlocal player = m.GetPlayer()\nif not player or not player.id then return end\nlocal role\nfor i=1,8 do\n    local name = s.roles[i]\n    local member = m.Party[name]\n    if not member or type(member.id) ~= \"number\" or member.id <= 0 then return end\n    for j=1,i-1 do\n        if m.Party[s.roles[j]].id == member.id then return end\n    end\n    if member.id == player.id then role = name end\nend\nif not role then return end\nlocal u,v\nif role == \"MT\" or role == \"ST\" then\n    if not s.blue then\n        local hand = TensorCore.mGetEntity(s.handID)\n        if not hand then return end\n        if Argus.getEntityAnimation(s.handID,1) == 4432 then s.blue=true end\n    end\n    if role == \"MT\" then\n        if s.blue then u,v=-5,12 else u,v=0,17 end\n    else\n        if s.blue then u,v=0,17 else u,v=-10,-10 end\n    end\nelseif role == \"H1\" then u,v=-7,12\nelseif role == \"H2\" then u,v=-15,9\nelseif role == \"D1\" then u,v=-4,5\nelseif role == \"D2\" then u,v=4,5\nelseif role == \"D3\" then u,v=15,9\nelseif role == \"D4\" then u,v=-9,-15\nelse return end\nlocal x,z = 100 + u*s.rx + v*s.fx, 100 + u*s.rz + v*s.fz\nm.FrameDirect(x,z,0.6)\nself.used = true\n\r\n",
