		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local t = TensorReactions_CurrentTimer\nif t > 34.3 then self.used = true return end\nlocal ms = (36.7 - t) * 1000\nif ms <= 0 then self.used = true return end\nif not self.shapes then self.shapes = {} self.seen = {} end\nlocal shapes, seen = self.shapes, self.seen\nfor k in pairs(shapes) do shapes[k] = nil end\nfor k in pairs(seen) do seen[k] = nil end\nlocal count = 0\nfor _, a in ipairs(Argus.getCurrentAOEs()) do\n    if a.contentID == 9213 and (a.aoeID == 18869) and not a.friendly and a.aoeLength == 40 then\n        if not seen[a.entityID] then\n            seen[a.entityID] = true\n            count = count + 1\n            shapes[count] = a\n        end\n    end\nend\nif count > 3 then self.used = true return end\nif count < 3 then return end\nlocal drawer = TensorCore.getStaticDrawer(0x80FFCC66)\nfor i = 1, count do\n    local a = shapes[i]\n    drawer:addTimedCone(ms, a.x, a.y, a.z, 40, math.pi / 6, a.heading)\nend\nself.used = true",
