		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- First visible tornado waves + four dolls. Complete snapshots only.\n-- Fish BV1Xd4y1Q72N 04:53/04:59 and 06:28.\nlocal now = TensorReactions_CurrentTimer\nif now < 33.4 or now > 36.4 then self.used=true; return end\nlocal s = data.stringTeaP1GuideV1\nif not s or not s.ready then return end\nlocal all = Argus.getCurrentAOEs()\nif type(all) ~= \"table\" then return end\nlocal waves, seen = {}, {}\nfor _,a in pairs(all) do\n    if a.aoeID == 18869 and a.contentID == 9213 and a.aoeCastType == 13 then\n        if not a.entityID or seen[a.entityID] then return end\n        if type(a.x)~=\"number\" or type(a.z)~=\"number\" or type(a.heading)~=\"number\" then return end\n        seen[a.entityID]=true\n        waves[#waves+1]={x=a.x,z=a.z,dx=math.sin(a.heading),dz=math.cos(a.heading)}\n    end\nend\nif #waves ~= 3 then return end\n-- Every cone must belong to a different known pond.\nlocal matched={}\nfor _,w in ipairs(waves) do\n    local match\n    for i,p in ipairs(s.ponds) do\n        if (w.x-100-p.x)^2+(w.z-100-p.z)^2 < 1 then match=i end\n    end\n    if not match or matched[match] then return end\n    matched[match]=true\nend\nlocal entities = TensorCore.entityList(\"contentid=9214\")\nif type(entities) ~= \"table\" then return end\nlocal dolls, count = {},0\nfor _,e in pairs(entities) do\n    if e and e.pos and Argus.getEntityModel(e.id)==11338 and Argus.isEntityVisible(e.id) then\n        local x,z=e.pos.x-100,e.pos.z-100\n        local r2=x*x+z*z\n        if r2<36 or r2>64 then return end\n        local u,v=x*s.rx+z*s.rz,x*s.fx+z*s.fz\n        if math.abs(u)<1 or math.abs(v)<1 then return end\n        local role = v>0 and (u<0 and \"D1\" or \"D2\") or (u>0 and \"D3\" or \"D4\")\n        if dolls[role] then return end\n        dolls[role]={id=e.id,x=e.pos.x,z=e.pos.z,u=u,v=v}\n        count=count+1\n    end\nend\nif count~=4 then return end\n\n-- Pond 7.6 + 0.6 margin; exhaust 8.8 + 0.5 margin.\n-- Melee stays farther from each pond than the three designated bait positions.\nlocal function safe(u,v,role,checkWave)\n    if u*u+v*v>19.3^2 then return false end\n    local x,z=100+u*s.rx+v*s.fx,100+u*s.rz+v*s.fz\n    local melee=role==\"D1\" or role==\"D2\"\n    local pondLimit=melee and 10.1 or 8.2\n    for _,p in ipairs(s.ponds) do\n        if (x-100-p.x)^2+(z-100-p.z)^2 < pondLimit^2 then return false end\n    end\n    local hits=0\n    for owner,doll in pairs(dolls) do\n        if (x-doll.x)^2+(z-doll.z)^2 < 9.3^2 then\n            if melee and owner~=role then return false end\n            hits=hits+1\n        end\n    end\n    if hits>1 then return false end\n    if checkWave then\n        for _,w in ipairs(waves) do\n            local dx,dz=x-w.x,z-w.z\n            local distance=math.sqrt(dx*dx+dz*dz)\n            if distance<40.5 and (distance<0.5 or (dx*w.dx+dz*w.dz)/distance>math.cos(math.pi/12+0.05)) then return false end\n        end\n    end\n    return true,x,z\nend\nlocal dodge,bait={},{}\nlocal preset={MT={-5,12},ST={0,17},H1={-7,12},H2={-15,9},D3={15,9},D4={-9,-15}}\n-- Fixed tank/healer assignments and the second (invisible) bait positions.\nfor role,p in pairs(preset) do\n    local ok,x,z=safe(p[1],p[2],role,false)\n    if not ok then return end\n    bait[role]={x=x,z=z}\nend\n-- Melee: actual quadrant doll, <=3.5 from its center and outside all other exhausts.\nfor _,role in ipairs({\"D1\",\"D2\"}) do\n    local doll=dolls[role]\n    local prefU,prefV=role==\"D1\" and -4 or 4,5\n    local best,cost\n    for radius=0.5,3.5,0.5 do\n        for step=0,71 do\n            local angle=step*math.pi/36\n            local u,v=doll.u+radius*math.sin(angle),doll.v+radius*math.cos(angle)\n            local ok,x,z=safe(u,v,role,true)\n            local score=(u-prefU)^2+(v-prefV)^2\n            if ok and (not cost or score<cost) then best={x=x,z=z};cost=score end\n        end\n    end\n    if not best then return end\n    dodge[role]=best; bait[role]=best\nend\n-- Sidestep toward the arena center after the three visible directions lock.\nlocal sidestep={H2={-12,9},D3={12,9},D4={-9,-12}}\nfor role,p in pairs(sidestep) do\n    local best,cost\n    for du=-2,2,0.25 do\n        for dv=-2,2,0.25 do\n            local u,v=p[1]+du,p[2]+dv\n            local ok,x,z=safe(u,v,role,true)\n            local score=du*du+dv*dv\n            if ok and (not cost or score<cost) then best={x=x,z=z};cost=score end\n        end\n    end\n    if not best then return end\n    dodge[role]=best\nend\nfor _,role in ipairs({\"MT\",\"ST\",\"H1\"}) do\n    local p=preset[role]\n    local ok,x,z=safe(p[1],p[2],role,true)\n    if not ok then return end\n    dodge[role]={x=x,z=z}\nend\ndata.stringTeaP1DollsV1={ready=true,dolls=dolls,waves=waves,dodge=dodge,bait=bait,capturedAt=now}\nself.used=true\n",
