		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- One queued worker in the native P1 doll window. No current-target restore rule.\nlocal s=data.stringTeaP1DollQT\nif s and s.done then self.used=true; return end\nlocal p=TensorCore.mGetPlayer()\nif not p or not p.alive then return end\nlocal target=TensorCore.mGetTarget()\nif not self.isDoll then\n    self.isDoll=function(e)\n        return e and e.contentid==9214 and Argus.getEntityModel(e.id)==11338\n    end\nend\nlocal isDoll=self.isDoll\nlocal own\nif not s or not s.dollID then\n    local tethers=Argus.getTethersOnEnt(p.id)\n    if type(tethers)~='table' then return end\n    for _,t in pairs(tethers) do\n        if t.type==17 and t.partnerid then\n            local e=TensorCore.mGetEntity(t.partnerid)\n            if isDoll(e) then\n                if own and own.id~=e.id then return end\n                own=e\n            end\n        end\n    end\nelse\n    own=TensorCore.mGetEntity(s.dollID)\n    if not isDoll(own) then own=nil end\nend\nif not s then\n    -- Targeting a doll can precede its first tether: hold now, identify only by tether.\n    if not own and not isDoll(target) then return end\n    if not AnyoneCore or type(AnyoneCore.Toggle)~='function' then return end\n    local api=TensorCore.API and TensorCore.API.TensorACR\n    if not api or type(api.getQuickToggles)~='function' then return end\n    local toggles=api.getQuickToggles()\n    if type(toggles)~='table' or not next(toggles) then return end\n    s={playerID=p.id,dollID=own and own.id,cd={},aoe={}}\n    data.stringTeaP1DollQT=s\n    local function hold(kind,group)\n        local before={}\n        for _,t in pairs(toggles) do\n            if type(t.var)=='string' and type(_G[t.var])=='boolean' then before[t.var]=_G[t.var] end\n        end\n        -- Save first so an interrupted call still has a cleanup record.\n        for var,value in pairs(before) do group[var]={before=value} end\n        AnyoneCore.Toggle(kind,false)\n        for var,value in pairs(before) do\n            if _G[var]==value then group[var]=nil else group[var].held=_G[var] end\n        end\n    end\n    hold('aoe',s.aoe)\n    hold('cd',s.cd)\n    -- Anyone's SMN exception is a separate live Quick Toggle, not an action request.\n    for _,t in pairs(toggles) do\n        if t.var=='ACR_TensorRuin3_HoldAOE' and type(_G[t.var])=='boolean' and not _G[t.var] then\n            s.cd[t.var]={before=false,held=true}\n            _G[t.var]=true\n        end\n    end\nend\nif s.playerID~=p.id then return end\nif own and not s.dollID then s.dollID=own.id end\nif not self.restore then\n    self.restore=function(group)\n        for var,v in pairs(group) do\n            if v.held==nil or _G[var]==v.held then _G[var]=v.before end\n        end\n        for var in pairs(group) do group[var]=nil end\n    end\nend\nlocal restore=self.restore\nif own and own.hp and type(own.hp.percent)=='number' and own.hp.percent>0 and own.hp.percent<25 then\n    s.below25=true\nend\n-- The existing native target-switch reaction moves off a low-HP doll first.\n-- A boss target alone never grants release; the owned doll's threshold is mandatory.\nif s.below25 and not isDoll(target) and not s.cdReleased then\n    restore(s.cd)\n    s.cdReleased=true\nend\nlocal dolls=TensorCore.entityList('contentid=9214')\nif type(dolls)~='table' then return end\nif (own and own.alive~=false) or (isDoll(target) and target.alive~=false) then return end\nfor _,e in pairs(dolls) do\n    if isDoll(e) and e.alive~=false then return end\nend\n-- Mechanic-completion cleanup also covers a doll consumed between two samples.\nrestore(s.cd)\nrestore(s.aoe)\ns.done=true\nself.used=true\n",
