		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- BV1Xd4y1Q72N 09:09-09:40: visible dodge, melee/tank baits, healer/ranged baits.\n-- One complete eight-AOE snapshot. Each later window belongs to its timeline node.\nlocal now=TensorReactions_CurrentTimer\nif now<62 or now>69.6 then self.used=true; return end\nif not self.initialized then\n    data.stringTeaP1Protean1V2={ready=false}\n    self.initialized=true\nend\nlocal s=data.stringTeaP1GuideV1\nif not s or not s.ready then return end\nif now<66.2 then return end\nlocal waves,seen,body={}, {}, nil\nfor _,a in ipairs(Argus.getCurrentAOEs()) do\n    if a.contentID==9211 and (a.aoeID==18466 or a.aoeID==18468)\n        and a.aoeCastType==13 and a.aoeLength==40 and not a.friendly then\n        if seen[a.entityID] then return end\n        seen[a.entityID]=true\n        waves[#waves+1]={x=a.x,z=a.z,dx=math.sin(a.heading),dz=math.cos(a.heading)}\n        if a.aoeID==18466 then\n            if body then return end\n            body={x=a.x,z=a.z,dx=math.sin(a.heading),dz=math.cos(a.heading)}\n        end\n    end\nend\nif #waves~=8 or not body then return end\nif (body.x-100)^2+(body.z-100)^2>4 then return end\n-- A displaced or differently facing boss does not satisfy this strategy's setup.\nif body.dx*s.fx+body.dz*s.fz<math.cos(math.pi/18) then return end\nfor _,a in ipairs(waves) do\n    if (a.x-body.x)^2+(a.z-body.z)^2>0.25 then return end\nend\nlocal function world(u,v)\n    return {x=body.x+u*s.rx+v*s.fx,z=body.z+u*s.rz+v*s.fz}\nend\nlocal function floorSafe(p)\n    if (p.x-100)^2+(p.z-100)^2>19.3^2 then return false end\n    for _,pond in ipairs(s.ponds) do\n        if (p.x-100-pond.x)^2+(p.z-100-pond.z)^2<8.2^2 then return false end\n    end\n    return true\nend\nlocal function coneSafe(p)\n    if not floorSafe(p) then return false end\n    for _,a in ipairs(waves) do\n        local dx,dz=p.x-a.x,p.z-a.z\n        local dist=math.sqrt(dx*dx+dz*dz)\n        if dist<0.1 or (dx*a.dx+dz*a.dz)/dist>math.cos(math.pi/12+0.06) then return false end\n    end\n    return true\nend\n-- Baiters stand 3 yalms from the boss center, inside its measured 3.5 hit radius.\nlocal first={MT={2.12,2.12},ST={0,-3},H1={-8,-10.3},H2={-10.3,-8},\n    D1={-3,0},D2={3,0},D3={10.3,-8},D4={8,-10.3}}\nlocal dodgePreferred={MT={2.12,2.12},ST={-1.5,-2.598},H1={-8,-10.3},H2={-10.3,-8},\n    D1={-3,0},D2={3,0},D3={10.3,-8},D4={8,-10.3}}\nlocal second={MT={5.3,5.3},ST={0,-6.5},H1={-2.12,-2.12},H2={-3,0},\n    D1={-5.3,5.3},D2={4.6,4.6},D3={3,0},D4={2.12,-2.12}}\nlocal result={ready=false,dodge={},first={},second={},gather=world(0,5),waves=waves,capturedAt=now}\nfor _,role in ipairs(s.roles) do\n    local p1,p2=first[role],second[role]\n    result.first[role],result.second[role]=world(p1[1],p1[2]),world(p2[1],p2[2])\n    if not floorSafe(result.first[role]) or not floorSafe(result.second[role]) then self.used=true; return end\n    local pref=dodgePreferred[role]\n    local angle=math.atan2(pref[1],pref[2])\n    local radius=math.sqrt(pref[1]^2+pref[2]^2)\n    local best,bestCost\n    for step=-10,10 do\n        local a=angle+step*math.pi/90\n        local p=world(radius*math.sin(a),radius*math.cos(a))\n        if coneSafe(p) then\n            local cost=step*step\n            if not bestCost or cost<bestCost then best,bestCost=p,cost end\n        end\n    end\n    if not best then self.used=true; return end\n    result.dodge[role]=best\nend\nif not floorSafe(result.gather) then self.used=true; return end\nresult.ready=true\ndata.stringTeaP1Protean1V2=result\nself.used=true\n",
							name = "MuAi 职能联动",
							uuid = "4910b693-eb4f-2f5e-8f03-b6b642307422",
