				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local ms = (75 - TensorReactions_CurrentTimer) * 1000\nif ms <= 0 then self.used = true return end\nlocal source = TensorCore.getEntityByGroup(\"ContentID\", {contentid=9211, subgroup=\"Highest HP\"})\nif not source then return end\nlocal party = TensorCore.getEntityByGroup(\"Party\", \"Number\")\nif not party then return end\nif not self.stringTeaTargets then self.stringTeaTargets = {} self.stringTeaDraws = {} self.stringTeaAttached = {} end\nlocal targets, draws, attached = self.stringTeaTargets, self.stringTeaDraws, self.stringTeaAttached\nfor k in pairs(targets) do targets[k] = nil end\nlocal p = source.pos\nlocal count = 0\nfor _, e in pairs(party) do\n    if e.alive then\n        count = count + 1\n        local q = e.pos\n        local d = (q.x-p.x)^2 + (q.z-p.z)^2\n        local rank = 1\n        for _, other in pairs(party) do\n            if other.alive and other.id ~= e.id then\n                local v = other.pos\n                local od = (v.x-p.x)^2 + (v.z-p.z)^2\n                if od < d or (od == d and other.id < e.id) then rank = rank + 1 end\n            end\n        end\n        if rank <= 4 then targets[rank] = e.id end\n    end\nend\nif count < 4 then\n    for k, uuid in pairs(draws) do Argus.deleteTimedShape(uuid) draws[k] = nil attached[k] = nil end\n    return\nend\nlocal drawer = TensorCore.getStaticDrawer(0x80FFCC66)\n-- Entity attachment follows movement; only a changed nearest-player assignment needs an update.\nfor i = 0, 4 do\n    local targetID = targets[i]\n    if draws[i] and attached[i] ~= targetID then\n        if not drawer:updateTimedConeOnEnt(draws[i], nil, source.id, 40, math.pi / 6, targetID) then\n            draws[i] = nil\n        end\n    end\n    if not draws[i] then\n        draws[i] = drawer:addTimedConeOnEnt(ms, source.id, 40, math.pi / 6, targetID)\n    end\n    attached[i] = targetID\nend",
