							aType = "Lua",
							actionLua = "-- Snapshot the three tornado telegraphs plus all four Sluice circles before swapping.\nlocal now=TensorReactions_CurrentTimer\nif now<109.2 or now>110.4 then self.used=true; return end\nlocal s=data.stringTeaP1Guide2V1\nlocal stage=data.stringTeaP1Protean2V1\nif not s or not s.ready or not stage or not stage.ready then return end\nlocal waves,circles,seen,pondSeen={},{},{},{}\nfor _,a in ipairs(Argus.getCurrentAOEs()) do\n    if a.contentID==9213 and a.aoeID==18869 and a.aoeCastType==13\n        and a.aoeLength==40 and not a.friendly then\n        if seen[a.entityID] then return end\n        seen[a.entityID]=true\n        local match\n        for i,p in ipairs(s.ponds) do\n            if (a.x-100-p.x)^2+(a.z-100-p.z)^2<0.25 then\n                if match or pondSeen[i] then return end\n                match=i\n            end\n        end\n        if not match then return end\n        pondSeen[match]=true\n        waves[#waves+1]={x=a.x,z=a.z,dx=math.sin(a.heading),dz=math.cos(a.heading)}\n    elseif a.contentID==9211 and a.aoeID==18865 and a.aoeCastType==2\n        and a.aoeLength==5 and not a.friendly then\n        if seen[a.entityID] then return end\n        seen[a.entityID]=true\n        circles[#circles+1]={x=a.x,z=a.z}\n    end\nend\nif #waves~=3 or #circles~=4 then return end\nlocal function safe(p)\n    if (p.x-100)^2+(p.z-100)^2>19.3^2 then return false end\n    for _,q in ipairs(s.ponds) do\n        if (p.x-100-q.x)^2+(p.z-100-q.z)^2<8.2^2 then return false end\n    end\n    for _,q in ipairs(circles) do\n        if (p.x-q.x)^2+(p.z-q.z)^2<5.5^2 then return false end\n    end\n    for _,a in ipairs(waves) do\n        local dx,dz=p.x-a.x,p.z-a.z\n        local length=math.sqrt(dx*dx+dz*dz)\n        if length<0.1 or (dx*a.dx+dz*a.dz)/length>math.cos(math.pi/12+0.06) then return false end\n    end\n    return true\nend\nfor _,role in ipairs(s.roles) do\n    local a,b=stage.second[role],stage.exit[role]\n    if not safe(a) or not safe(b) then self.used=true; return end\n    -- The final move begins after the body protean but before tornado telegraphs end.\n    for i=1,19 do\n        local f=i/20\n        if not safe({x=a.x+(b.x-a.x)*f,z=a.z+(b.z-a.z)*f}) then self.used=true; return end\n    end\nend\nstage.tornadoWaves=waves\nstage.sluices=circles\nstage.lateCapturedAt=now\nstage.lateReady=true\nself.used=true\n",
