							actionLua = "-- Fish guide BV1hj411K7hF: 1256 left/up half, 3478 opposite, clockwise.\nlocal t=TensorReactions_CurrentTimer\nif t<80 or t>200.8 then self.used=true return end\nlocal owner=data.stringTeaLc1Preview\nif not owner or owner.version~=1 then self.used=true return end\nlocal x,z=eventArgs.castPosX,eventArgs.castPosZ\nif eventArgs.spellID~=18480 or eventArgs.entityContentID~=9218 or not x or not z then self.used=true return end\nlocal dx,dz=x-100,z-100\nlocal radius=math.sqrt(dx*dx+dz*dz)\nif radius<13 or radius>15 then self.used=true return end\n-- Exactly N, NW, W or SW belongs to 1256; use the actual first hit only.\nif not (dx < -2 or math.abs(dx)<=2 and dz<0) then self.used=true return end\nlocal old=data.stringTeaP15GuideV1\nif old and old.owner==owner then self.used=true return end\nlocal s={owner=owner,version=1,ready=true,points={},roles={\"MT\",\"ST\",\"H1\",\"H2\",\"D1\",\"D2\",\"D3\",\"D4\"}}\nlocal function point(step,radius,tangent,opposite)\n    local a=step*math.pi/4\n    local fx=dx*math.cos(a)-dz*math.sin(a)\n    local fz=dx*math.sin(a)+dz*math.cos(a)\n    local length=math.sqrt(fx*fx+fz*fz)\n    fx,fz=fx/length,fz/length\n    if opposite then fx,fz=-fx,-fz end\n    return {x=100+fx*radius-fz*tangent,z=100+fz*radius+fx*tangent}\nend\nlocal schedules={[1]={{202.35,0,13.5},{204.55,1,13.5},{207.55,2,13.5},{209.05,2,19},{211.15,3,19},{213.4,4,19},{216.95,5,19},{217.85,6,19},{220.05,7,19},{225.5,-1,0}},[2]={{202.35,0,13.5},{204.55,1,13.5},{209.05,2,13.5},{211.15,3,19},{213.4,4,19},{216.95,5,19},{217.85,6,19},{220.05,7,19},{225.5,-1,0}},[3]={{202.35,0,13.5},{204.55,1,13.5},{206.8,2,13.5},{212.25,3,13.5},{213.75,3,19},{215.6,4,19},{217.85,5,19},{220.05,6,19},{225.5,-1,0}},[4]={{202.35,0,13.5},{204.55,1,13.5},{206.8,2,13.5},{213.75,3,13.5},{215.6,4,19},{217.85,5,19},{220.05,6,19},{225.5,-1,0}},[5]={{202.35,0,19},{204.55,1,19},{207.55,2,19},{209.05,3,19},{211.15,3,13.5},{213.4,4,13.5},{216.95,5,13.5},{220.05,5,19},{225.5,-1,0}},[6]={{202.35,0,19},{204.55,1,19},{207.55,2,19},{209.05,3,19},{211.15,3,13.5},{213.4,4,13.5},{218.45,5,13.5},{220.05,5,19},{225.5,-1,0}},[7]={{202.35,0,19},{204.55,1,19},{206.8,2,19},{212.25,3,19},{213.75,4,19},{215.6,5,13.5},{217.85,6,13.5},{221.55,7,13.5},{223.05,7,19},{225.5,-1,0}},[8]={{202.35,0,19},{204.55,1,19},{206.8,2,19},{212.25,3,19},{213.75,4,19},{215.6,5,13.5},{217.85,6,13.5},{223.05,7,13.5},{225.5,-1,0}}}\nfor n=1,8 do\n    local opposite=n==3 or n==4 or n==7 or n==8\n    local odd=n%2==1\n    local rows=schedules[n]\n    local out={}\n    for i=1,#rows do\n        local row=rows[i]\n        local p=row[2]==-1 and {x=100,z=100} or point(row[2],row[3],odd and 0 or -4,opposite)\n        if row[3]==19 then p=point(row[2],19,odd and 0 or -2,opposite) end\n        p.untilTime=row[1]\n        out[i]=p\n    end\n    s.points[n]=out\nend\ndata.stringTeaP15GuideV1=s\nself.used=true\n",
