							actionLua = "local s = data.stringTeaLc1Preview\nif not s or s.version ~= 1 then self.used = true return end\nlocal n, id = eventArgs.markerID - 78, eventArgs.entityID\nif n < 1 or n > 8 then self.used = true return end\nlocal member = false\nfor _, e in pairs(TensorCore.getEntityByGroup(\"Party\", \"Number\") or {}) do if e.id == id then member = true break end end\nif not member then self.used = true return end\nlocal before = s.count\nif (s.targets[n] and s.targets[n] ~= id) or (s.seen[id] and s.seen[id] ~= n) then\n    s.invalid = true\nelseif not s.targets[n] then\n    s.targets[n], s.seen[id] = id, n\n    s.count = s.count + 1\nend\nd(string.format(\"[String TEA LC1] marker=%d entity=%d count=%d->%d invalid=%s\", n, id, before, s.count, tostring(s.invalid)))\nself.used = true",
