						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<209.05 or now>=213.75 then return end\nlocal owner=data.stringTeaLc1Preview\nif not owner or owner.version~=1 or owner.invalid or owner.count~=8 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~=\"table\" or type(m.GetPlayer)~=\"function\" or type(m.FrameDirect)~=\"function\" then return end\nlocal player=m.GetPlayer()\nif not player or not player.id then return end\nlocal number=owner.seen[player.id]\nif not number or number<1 or number>8 or owner.targets[number]~=player.id then return end\n\nlocal s=data.stringTeaP15GuideV1\nif not s or not s.ready or s.owner~=owner then return end\nlocal role\nfor i=1,8 do\n    local name=s.roles[i]\n    local member=m.Party[name]\n    if not member or type(member.id)~=\"number\" or member.id<=0 then return end\n    for j=1,i-1 do if m.Party[s.roles[j]].id==member.id then return end end\n    if member.id==player.id then role=name end\nend\nif not role then return end\nlocal rows=s.points[number]\nfor i=1,#rows do\n    local point=rows[i]\n    if now<point.untilTime then\n        m.FrameDirect(point.x,point.z,0.6)\n        self.used=true\n        return\n    end\nend\n",
