							actionLua = "local now=TensorReactions_CurrentTimer\nif now<262.8 or now>=275.5 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~=\"table\" or type(m.GetPlayer)~=\"function\" or type(m.FrameDirect)~=\"function\" then return end\nlocal player=m.GetPlayer()\nif not player or not player.id then return end\nlocal s=data.stringTeaP2NisiGuideV1\nif not s then\n    s={roles={\"MT\",\"ST\",\"H1\",\"H2\",\"D1\",\"D2\",\"D3\",\"D4\"},ids={2222,2223,2137,2138},partners={5,6,7,8,1,2,3,4},rounds={}}\n    function s.color(entity)\n        local color=0\n        for i=1,4 do\n            local b=TensorCore.getBuff(entity,s.ids[i])\n            if b and b.duration and b.duration>0 then\n                if color~=0 then return -1 end\n                color=i\n            end\n        end\n        return color\n    end\n    data.stringTeaP2NisiGuideV1=s\nend\nlocal me\nfor i=1,8 do\n    local member=m.Party[s.roles[i]]\n    if not member or type(member.id)~=\"number\" or member.id<=0 then return end\n    for j=1,i-1 do if m.Party[s.roles[j]].id==member.id then return end end\n    if member.id==player.id then me=i end\nend\nif not me then return end\nlocal r=s.rounds[1]\nif not r or now<r.last then\n    r={last=now,done={},members={}}\n    s.rounds[1]=r\nend\nfor i=1,8 do\n    local id=m.Party[s.roles[i]].id\n    if r.members[i] and r.members[i]~=id then r.done={} end\n    r.members[i]=id\nend\nr.last=now\nr.view=player.id\nr.target=nil\nr.x=nil\nr.z=nil\nr.status=\"waiting\"\nif r.done[player.id] then r.status=\"complete\";return end\nlocal partner=m.Party[s.roles[s.partners[me]]]\nlocal e=TensorCore.mGetEntity(player.id)\nlocal p=TensorCore.mGetEntity(partner.id)\nif not e or not p then r.status=\"missing_entity\";return end\nlocal a,b=s.color(e),s.color(p)\nif a<0 or b<0 or a>0 and b>0 and a~=b then r.status=\"invalid_colors\";return end\nif 1==1 and (me==2 or me==6) then\n    local cc=r.cc and TensorCore.mGetEntity(r.cc)\n    if not cc then\n        for _,candidate in pairs(TensorCore.entityList(\"contentid=9218\")) do\n            if candidate.alive and Argus.getEntityModel(candidate.id)==11342 then\n                if cc then return end\n                cc=candidate\n            end\n        end\n        if cc then r.cc=cc.id end\n    end\n    if not cc or not cc.pos then return end\n    if not r.front and now>=269.2 and now<272.8 then\n        for _,aoe in ipairs(Argus.getCurrentAOEs()) do\n            if aoe.aoeID==19058 and aoe.entityID==cc.id then\n                r.front={x=aoe.x+4.5*math.sin(aoe.heading),z=aoe.z+4.5*math.cos(aoe.heading)}\n            end\n        end\n    end\n    if a>0 and a==b then\n        r.status=\"complete\"\n        if me==2 and now>=272.9 and r.front then\n            r.x,r.z=r.front.x,r.front.z\n            r.status=\"return_front\"\n            m.FrameDirect(r.x,r.z,0.6)\n        end\n        return\n    end\n    if me==6 then\n        r.x=cc.pos.x-4.5*math.sin(cc.pos.h)\n        r.z=cc.pos.z-4.5*math.cos(cc.pos.h)\n        r.status=\"wait_behind_chaser\"\n        m.FrameDirect(r.x,r.z,0.6)\n        return\n    end\n    if now<269.2 or not r.front then r.status=\"wait_spin_cast\";return end\nend\nif a>0 and a==b then\n    r.done[player.id]=true\n    r.status=\"complete\"\n    return\nend\nif a==0 and b==0 then r.status=\"missing_poison\";return end\n-- Fish sep modified: the DPS approaches the fixed TN partner in passes 1 and 2.\nif me<=4 and not (1==1 and me==2) then r.status=\"hold_for_dps\";return end\nlocal pos=p.pos\nif not pos or type(pos.x)~=\"number\" or type(pos.z)~=\"number\" then return end\nif (pos.x-100)^2+(pos.z-100)^2>400 then r.status=\"outside_arena\";return end\nr.target=p.id\nr.x,r.z=pos.x,pos.z\nr.status=\"approach_partner\"\nm.FrameDirect(pos.x,pos.z,0.6)\nself.used=true\n",
