					{
						data = 
						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<296 or now>=306.7 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal roles={'MT','ST','H1','H2','D1','D2','D3','D4'}\nlocal es,seen={},{}\nlocal me,water,light,weakWater\nlocal function has(e,id)\n    local b=TensorCore.getBuff(e,id)\n    return b and b.duration and b.duration>0\nend\nfor i=1,8 do\n    local p=m.Party[roles[i]]\n    if not p or not p.id or seen[p.id] then return end\n    seen[p.id]=true\n    es[i]=TensorCore.mGetEntity(p.id)\n    if not es[i] or not es[i].pos then return end\n    if p.id==player.id then me=i end\n    if has(es[i],2142) then if water then return end;water=i end\n    if has(es[i],2143) then if light then return end;light=i end\n    if has(es[i],2144) then if weakWater then return end;weakWater=i end\nend\nif not me or not water or not light or water==light or me<=2 then return end\nlocal round=2\ndata.stringTeaP2WaterGuideV1=data.stringTeaP2WaterGuideV1 or {passed={}}\nlocal s=data.stringTeaP2WaterGuideV1\nlocal wg,lg={},{}\nif round==1 then\n    if water<3 or water>4 or light<5 then return end\n    wg={water};lg={light,7-water}\n    for _,i in ipairs({5,7,8}) do if i~=light then wg[#wg+1]=i end end\nelseif round==2 then\n    if light<3 or light>4 or water~=5 and water~=7 and water~=8 then return end\n    wg={water};lg={light,7-light}\n    for _,i in ipairs({5,7,8}) do if i~=water then wg[#wg+1]=i end end\nelse\n    if water<3 or water>4 or light~=7-water or weakWater~=5 and weakWater~=7 and weakWater~=8 then return end\n    wg={water};lg={light,weakWater}\n    for _,i in ipairs({5,7,8}) do if i~=weakWater then wg[#wg+1]=i end end\nend\nfor _,i in ipairs(wg) do if has(es[i],2144) then return end end\nfor _,i in ipairs(lg) do if has(es[i],2145) then return end end\n-- Transfer takes priority until this fixed pair has received the same Nisi.\nif round<=2 then\n    local other=({5,6,7,8,1,2,3,4})[me]\n    local shared=false\n    for _,id in ipairs({2222,2223,2137,2138}) do\n        if has(es[me],id) and has(es[other],id) then shared=true end\n    end\n    local passKey=round..':'..player.id\n    if shared then s.passed[passKey]=true end\n    if not s.passed[passKey] then\n        local fixed=data.stringTeaP2NisiGuideV1\n        local previous=fixed and fixed.rounds[round]\n        if previous and previous.done[player.id] then s.passed[passKey]=true end\n    end\n    if not s.passed[passKey] then return end\n    if round==1 and me==6 and now<275.5 then return end\nend\nlocal group,slot\nfor j,i in ipairs(wg) do if me==i then group='water';slot=j end end\nfor j,i in ipairs(lg) do if me==i then group='light';slot=j end end\nif not group then return end\nlocal x,z\nif group=='light' then\n    if round<3 then x,z=100,slot==1 and 102 or 98\n    else x,z=slot==1 and 90 or 86,slot==1 and 100 or 96 end\nelse\n    local cx=round==1 and 84 or round==2 and 118 or 114\n    local dir=round==1 and 1 or -1\n    if slot==1 then x,z=cx,100\n    elseif slot==2 then x,z=cx+dir*4,96\n    elseif slot==3 then x,z=cx+dir*4,104\n    else x,z=cx+dir*6,100 end\nend\nlocal key=round..':'..player.id..':'..group..':'..slot\nif s.key~=key then\n    d(string.format('[String TEA P2] water round=%d view=%s group=%s slot=%d water=%s lightning=%s point=%.2f,%.2f',round,roles[me],group,slot,roles[water],roles[light],x,z))\n    s.key=key\nend\ns.x,s.z,s.view=x,z,player.id\nm.FrameDirect(x,z,0.6)\nself.used=true\n",
