							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<316.0 or now>=333.0 then return end\nif 3==3 then\n    local broken=data.stringTeaP2NisiShieldBrokenAt\n    if not broken or broken<316 or broken>now then return end\nend\nlocal m=MuAiGuide\nif not m or type(m.Party)~=\"table\" or type(m.GetPlayer)~=\"function\" or type(m.FrameDirect)~=\"function\" then return end\nlocal player=m.GetPlayer()\nif not player or not player.id then return end\nlocal s=data.stringTeaP2NisiMatchV1\nif not s then\n    s={roles={\"MT\",\"ST\",\"H1\",\"H2\",\"D1\",\"D2\",\"D3\",\"D4\"},poisons={2222,2223,2137,2138},vaccines={2224,2225,2139,2140},rounds={}}\n    function s.color(e,ids)\n        local result=0\n        for i=1,4 do\n            local b=TensorCore.getBuff(e,ids[i])\n            if b and b.duration and b.duration>0 then\n                if result~=0 then return -1 end\n                result=i\n            end\n        end\n        return result\n    end\n    data.stringTeaP2NisiMatchV1=s\nend\nlocal me\nfor i=1,8 do\n    local member=m.Party[s.roles[i]]\n    if not member or type(member.id)~=\"number\" or member.id<=0 then return end\n    for j=1,i-1 do if m.Party[s.roles[j]].id==member.id then return end end\n    if member.id==player.id then me=i end\nend\nif not me then return end\nlocal r=s.rounds[3]\nif not r or now<r.last then r={last=now,done={},members={}};s.rounds[3]=r end\nfor i=1,8 do\n    local id=m.Party[s.roles[i]].id\n    if r.members[i] and r.members[i]~=id then r.done={} end\n    r.members[i]=id\nend\nr.last,r.view=now,player.id\nr.target,r.x,r.z=nil,nil,nil\nr.status=\"waiting\"\nif r.done[player.id] then r.status=\"complete\";return end\nlocal e=TensorCore.mGetEntity(player.id)\nif not e then return end\nlocal current,needed=s.color(e,s.poisons),s.color(e,s.vaccines)\nif current<0 or needed<=0 then r.status=\"invalid_or_missing_status\";return end\nif current>0 then\n    if current==needed then r.done[player.id]=true;r.status=\"complete\"\n    else r.status=\"hold_poison_for_receiver\" end\n    return\nend\nlocal target\nfor i=1,8 do\n    local other=TensorCore.mGetEntity(r.members[i])\n    if not other then r.status=\"incomplete_party\";return end\n    local color=s.color(other,s.poisons)\n    if color<0 then r.status=\"invalid_party_status\";return end\n    if color==needed then\n        if target then r.status=\"ambiguous_poison_holder\";return end\n        target=other\n    end\nend\nif not target or not target.pos then r.status=\"missing_poison_holder\";return end\nlocal p=target.pos\nif type(p.x)~=\"number\" or type(p.z)~=\"number\" or (p.x-100)^2+(p.z-100)^2>400 then return end\nr.target,r.x,r.z=target.id,p.x,p.z\nr.status=\"vaccine_seeks_poison\"\nif r.loggedTarget~=target.id or r.loggedView~=player.id then\n    d(string.format(\"[String TEA P2] pass 3 vaccine=%d player=%d target=%d timer=%.3f\",needed,player.id,target.id,now))\n    r.loggedTarget,r.loggedView=target.id,player.id\nend\nm.FrameDirect(p.x,p.z,0.6)\nself.used=true\n",
