		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<336.3 or now>=356.5 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal s=data.stringTeaP2IceQueueV2\nif not s then\n    s={roles={'MT','ST','H1','H2','D1','D2','D3','D4'},poison={2222,2223,2137,2138},vaccine={2224,2225,2139,2140},rank={0,1,3,2}}\n    s.members,s.current,s.arrived,s.anchors={},{},{},{}\n    for i=1,4 do s.anchors[i]={count=0,x=0,d=0,rank=s.rank[i]} end\n    function s.color(e,ids)\n        local c=0\n        for i,id in ipairs(ids) do\n            local b=TensorCore.getBuff(e,id)\n            if b and b.duration and b.duration>0 then if c~=0 then return -1 end;c=i end\n        end\n        return c\n    end\n    function s.entity(id,cid,model)\n        local e=id and TensorCore.mGetEntity(id)\n        if e and e.pos and Argus.getEntityModel(e.id)==model then return e end\n        local found\n        for _,v in pairs(TensorCore.entityList('contentid='..cid)) do\n            if v.pos and Argus.getEntityModel(v.id)==model and Argus.isEntityVisible(v.id) then\n                if found then return end;found=v\n            end\n        end\n        return found\n    end\n    data.stringTeaP2IceQueueV2=s\nend\nlocal me,entity,need,current\nlocal seen,counts={},{0,0,0,0}\nfor i,r in ipairs(s.roles) do\n    local p=m.Party[r]\n    if not p or not p.id or seen[p.id] then return end\n    seen[p.id]=true\n    local e=TensorCore.mGetEntity(p.id)\n    if not e or not e.pos then return end\n    local n,c=s.color(e,s.vaccine),s.color(e,s.poison)\n    if n<=0 or c<0 then return end\n    counts[n]=counts[n]+1\n    s.members[i],s.current[i]=e,c\n    if p.id==player.id then me,entity,need,current=i,e,n,c end\nend\nif not me then return end\nfor i=1,4 do if counts[i]~=2 then return end end\nlocal ice=s.entity(s.ice,9219,11393)\nlocal cc=s.entity(s.cc,9218,11342)\nif not ice or not cc then return end\ns.ice,s.cc=ice.id,cc.id\nlocal x,z,stage\nif me==2 and now<348.7 then\n    -- Bring Cruise Chaser south of the western ice, then join the queue on its cast.\n    x,z=ice.pos.x,ice.pos.z+5;stage='bring_chaser'\nelse\n    local c=current>0 and current or need\n    local distance=4.5+2.8*s.rank[c]\n    local lineX=ice.pos.x+1.5\n    -- First approach the broad color area. Once nearby, follow the real queue.\n    if (entity.pos.x-lineX)^2+(entity.pos.z-(ice.pos.z-distance))^2<=8^2 then s.arrived[player.id]=true end\n    if s.arrived[player.id] then\n        for i=1,4 do local a=s.anchors[i];a.count,a.x,a.d=0,0,0 end\n        for i,e in ipairs(s.members) do\n            local color=s.current[i]\n            local depth=ice.pos.z-e.pos.z\n            if color>0 and not (i==2 and now<348.7) and depth>=3.5 and depth<=16 and math.abs(e.pos.x-lineX)<=4 then\n                local a=s.anchors[color];a.count=a.count+1;a.x=a.x+e.pos.x;a.d=a.d+depth\n            end\n        end\n        for _,a in ipairs(s.anchors) do if a.count>0 then a.x=a.x/a.count;a.d=a.d/a.count end end\n        local lo,hi=3.5,16\n        local front,back\n        for color,a in ipairs(s.anchors) do if a.count>0 and color~=c then\n            local delta=s.rank[c]-s.rank[color]\n            if delta>0 then\n                lo=math.max(lo,a.d+2.6*delta)\n                if not front or a.rank>front.rank then front=a end\n            else\n                hi=math.min(hi,a.d+2.6*delta)\n                if not back or a.rank<back.rank then back=a end\n            end\n        end end\n        local own=s.anchors[c]\n        if lo>hi then\n            -- User preference: insert into the actual gap even when others leave too little space.\n            if front and back then\n                local t=(s.rank[c]-front.rank)/(back.rank-front.rank)\n                lineX=front.x+(back.x-front.x)*t\n                distance=front.d+(back.d-front.d)*t\n            elseif front then lineX,distance=front.x,front.d+2.6\n            elseif back then lineX,distance=back.x,back.d-2.6 end\n            distance=math.max(3.5,math.min(16,distance))\n        elseif own.count>0 then\n            lineX,distance=own.x,own.d\n        elseif front and back then\n            lineX=(front.x+back.x)/2;distance=(lo+hi)/2\n        elseif front then\n            lineX=front.x;distance=lo\n        elseif back then\n            lineX=back.x;distance=hi\n        end\n        if lo<=hi then distance=math.max(lo,math.min(hi,distance)) end\n    end\n    if now<348.7 then\n        x,z=lineX+(current==0 and 2.8 or 0),ice.pos.z-distance\n        stage='queue_'..c\n        if entity.pos.x>96 and math.abs(entity.pos.z-z)>1 then x=96 end\n    else\n        if current>0 and current~=need then return end\n        if not s.wind then\n            local dx,dz=ice.pos.x-cc.pos.x,ice.pos.z-cc.pos.z\n            local len=math.sqrt(dx*dx+dz*dz)\n            if len<3 or len>14 then return end\n            s.wind={x=cc.pos.x,z=cc.pos.z,ux=dx/len,uz=dz/len}\n        end\n        local w=s.wind\n        x,z=lineX,ice.pos.z-distance\n        -- Preserve the selected queue depth and keep the point behind the ice.\n        local dx,dz=x-w.x,z-w.z\n        local len=math.sqrt(dx*dx+dz*dz)\n        local projection=((ice.pos.x-w.x)*dx+(ice.pos.z-w.z)*dz)/len\n        local lateral=math.abs((ice.pos.x-w.x)*dz-(ice.pos.z-w.z)*dx)/len\n        if projection<=0 or projection>=len then return end\n        if lateral>2.3 then\n            -- Keep the chosen queue depth, but move sideways into the actual ice shadow.\n            if math.abs(ice.pos.z-w.z)<1 then return end\n            if (z-w.z)/(ice.pos.z-w.z)<=1 then return end\n            x=w.x+(ice.pos.x-w.x)*(z-w.z)/(ice.pos.z-w.z)\n        end\n        stage='ice_los_'..c\n    end\nend\nif (x-100)^2+(z-100)^2>19.6^2 then return end\nlocal key=player.id..':'..stage\nif s.key~=key then d(string.format('[String TEA P2] ice role=%s stage=%s point=%.2f,%.2f',s.roles[me],stage,x,z));s.key=key end\nm.FrameDirect(x,z,0.6)\nself.used=true",
