						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<485 or now>=500 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal g=data.stringTeaLateGuideV1\nif not g then\n    g={roles={'MT','ST','H1','H2','D1','D2','D3','D4'},members={},byID={}}\n    function g.buff(e,id)\n        local b=TensorCore.getBuff(e,id)\n        return b and b.duration and b.duration>0\n    end\n    function g.entity(cid,model)\n        local found\n        for _,e in pairs(TensorCore.entityList('contentid='..cid)) do\n            if e.pos and Argus.getEntityModel(e.id)==model then\n                if found then return end\n                found=e\n            end\n        end\n        return found\n    end\n    function g.point(x,z)\n        if type(x)~='number' or type(z)~='number' or x~=x or z~=z then return end\n        if (x-100)^2+(z-100)^2>19.7^2 then return end\n        m.FrameDirect(x,z,0.6)\n    end\n    data.stringTeaLateGuideV1=g\nend\nfor id in pairs(g.byID) do g.byID[id]=nil end\nlocal me\nfor i,r in ipairs(g.roles) do\n    local p=m.Party[r]\n    if not p or not p.id or g.byID[p.id] then return end\n    local e=TensorCore.mGetEntity(p.id)\n    if not e or not e.pos then return end\n    g.members[i],g.byID[p.id]=e,i\n    if p.id==player.id then me=i end\nend\nif not me then return end\nlocal e=g.members[me]\nlocal bj=g.entity(9216,11340)\nlocal cc=g.entity(9218,11342)\nif not bj or not cc or math.abs(bj.pos.x-cc.pos.x)<8 then return end\nlocal counts={0,0,0,0}\nlocal kind\nfor i,p in ipairs(g.members) do\n    local k=4\n    -- These mechanic statuses are present with duration=0 in the live replay API.\n    if TensorCore.getBuff(p,1121) then k=1 elseif TensorCore.getBuff(p,1123) then k=2 elseif TensorCore.getBuff(p,1124) then k=3 end\n    counts[k]=counts[k]+1\n    if i==me then kind=k end\nend\nfor i=1,4 do if counts[i]~=2 then return end end\nif TensorCore.getBuff(e,1119) then return end\nlocal x,z\nif kind==1 then\n    x,z=bj.pos.x<100 and 80.7 or 119.3,100\nelseif kind==2 or kind==4 then\n    local boss=kind==2 and (bj.pos.x>cc.pos.x and bj or cc) or (bj.pos.x<cc.pos.x and bj or cc)\n    x,z=boss.pos.x,boss.pos.z+(me<=4 and -2 or 2)\nelse\n    -- Fish: support west, damage east. The Chaser-side player baits its third cone.\n    local west=me<=4\n    local chaserSide=(cc.pos.x<100)==west\n    x,z=100+(west and -1 or 1)*(chaserSide and 15 or 19.3),100\nend\ng.point(x,z)\n\nself.used=true\n",
