						{
							aType = "Lua",
							actionLua = "-- TEA Temporal Stasis: BossMod 045e1e98479e4328dd09f1fae4c8e0372890cda9, P3TemporalStasis.cs.\n-- Closest-player baits; full 90-degree angle remains pending boundary verification.\n-- Source CID/model and hit times checked against 20260925-0014-887-6.txt.\nlocal now = TensorReactions_CurrentTimer\nlocal ms = (505.1 - now) * 1000\nif ms <= 0 then self.used = true return end\nlocal source = self.stringTeaStasisSource and TensorCore.mGetEntity(self.stringTeaStasisSource)\nif not source or not Argus.isEntityVisible(source.id) then\n    source = nil\n    for _, e in pairs(TensorCore.entityList(\"contentid=9218\")) do\n        if Argus.getEntityModel(e.id) == 11342 and Argus.isEntityVisible(e.id) then\n            if source then source = nil break end\n            source = e\n        end\n    end\n    self.stringTeaStasisSource = source and source.id\nend\nlocal party = TensorCore.getEntityByGroup(\"Party\", \"Number\")\nlocal count = 0\nif party then for _, e in pairs(party) do if e.alive and e.pos then count = count + 1 end end end\nlocal target\nif source and source.pos and count == 8 then\n    local p = source.pos\n    for _, e in pairs(party) do\n        local dx, dz = e.pos.x - p.x, e.pos.z - p.z\n        local distance = dx * dx + dz * dz\n        local order = 1\n        for _, other in pairs(party) do\n            local ox, oz = other.pos.x - p.x, other.pos.z - p.z\n            local od = ox * ox + oz * oz\n            if od < distance or (od == distance and other.id < e.id) then order = order + 1 end\n        end\n        if order == 1 then target = e break end\n    end\nend\nif not target then\n    if self.stringTeaStasisDraw then Argus.deleteTimedShape(self.stringTeaStasisDraw) self.stringTeaStasisDraw = nil end\n    return\nend\nlocal drawer = TensorCore.getMoogleDrawer()\nif not self.stringTeaStasisDraw then\n    self.stringTeaStasisDraw = drawer:addTimedConeOnEnt(ms, source.id, 30, math.pi / 2, target.id)\nelseif self.stringTeaStasisTarget ~= target.id then\n    if not drawer:updateTimedConeOnEnt(self.stringTeaStasisDraw, nil, source.id, nil, nil, target.id) then\n        self.stringTeaStasisDraw = nil\n        return\n    end\nend\nself.stringTeaStasisTarget = target.id\nif now >= 500 and self.stringTeaStasisDraw then self.used = true end",
