		{
			data = 
			{
				displayPath = "P3",
				name = "动态指路",
				uuid = "a1449728-3ce7-d6ce-a53f-dbaba5975d6f",
			},
			objectType = "folder",
		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<545 or now>=562.5 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal g=data.stringTeaLateGuideV1\nif not g then\n    g={roles={'MT','ST','H1','H2','D1','D2','D3','D4'},members={},byID={}}\n    function g.buff(e,id)\n        local b=TensorCore.getBuff(e,id)\n        return b and b.duration and b.duration>0\n    end\n    function g.entity(cid,model)\n        local found\n        for _,e in pairs(TensorCore.entityList('contentid='..cid)) do\n            if e.pos and Argus.getEntityModel(e.id)==model then\n                if found then return end\n                found=e\n            end\n        end\n        return found\n    end\n    function g.point(x,z)\n        if type(x)~='number' or type(z)~='number' or x~=x or z~=z then return end\n        if (x-100)^2+(z-100)^2>19.7^2 then return end\n        m.FrameDirect(x,z,0.6)\n    end\n    data.stringTeaLateGuideV1=g\nend\nfor id in pairs(g.byID) do g.byID[id]=nil end\nlocal me\nfor i,r in ipairs(g.roles) do\n    local p=m.Party[r]\n    if not p or not p.id or g.byID[p.id] then return end\n    local e=TensorCore.mGetEntity(p.id)\n    if not e or not e.pos then return end\n    g.members[i],g.byID[p.id]=e,i\n    if p.id==player.id then me=i end\nend\nif not me then return end\nlocal e=g.members[me]\nlocal s=g.inception\nif not s then\n    if now>=552 then return end\n    local alex=g.entity(9220,11347)\n    if not alex or math.abs(alex.pos.z-100)<15 then return end\n    local spheres,owners,west,east={},{},{},{}\n    for source,links in pairs(Argus.getCurrentTethers()) do\n        local orb=TensorCore.mGetEntity(source)\n        if orb and orb.contentid==9221 and Argus.getEntityModel(source)==11344 and orb.pos then\n            for _,link in pairs(links) do\n                if link.type==12 and g.byID[link.targetid] then\n                    if owners[link.targetid] or spheres[source] then return end\n                    local v={id=source,owner=link.targetid,x=orb.pos.x,z=orb.pos.z}\n                    spheres[source]=v;owners[v.owner]=v\n                    local side=v.x<100 and west or east;side[#side+1]=v\n                end\n            end\n        end\n    end\n    if #west~=2 or #east~=2 then return end\n    table.sort(west,function(a,b)return a.z<b.z end)\n    table.sort(east,function(a,b)return a.z<b.z end)\n    s={owners=owners,points={},north=alex.pos.z<100,crystalRoles={}}\n    for side,list in ipairs({west,east}) do\n        for index,v in ipairs(list) do\n            local angle=s.north and (index==1 and math.pi/2 or math.pi*3/4) or (index==1 and math.pi/4 or math.pi/2)\n            if side==2 then angle=-angle end\n            s.points[v.owner]={x=100+18.8*math.sin(angle),z=100+18.8*math.cos(angle)}\n        end\n    end\n    for i,p in ipairs(g.members) do if not owners[p.id] then s.crystalRoles[#s.crystalRoles+1]=i end end\n    if #s.crystalRoles~=4 then return end\n    g.inception=s\n    d('[String TEA P3] inception complete sphere snapshot=4 crystal complement=4')\nend\nlocal orb=s.owners[player.id]\nif orb then\n    local live=TensorCore.mGetEntity(orb.id)\n    if live and Argus.isEntityVisible(orb.id) then\n        local p=s.points[player.id];g.point(p.x,p.z)\n    end\n    return\nend\nif now<552.5 or now>=558.3 then return end\nif not s.crystals then\n    -- Four marked players choose the nearest complete one-to-one arrangement.\n    -- The existing preposition determines priority; MuAi role order breaks ties.\n    local z=100+(s.north and 13 or -13)\n    local spots={{x=94.8,z=z-5.2},{x=105.2,z=z-5.2},{x=94.8,z=z+5.2},{x=105.2,z=z+5.2}}\n    local best,cost,used,pick=nil,math.huge,{},{}\n    local function solve(k,total)\n        if k==5 then if total<cost then cost=total;best={pick[1],pick[2],pick[3],pick[4]} end;return end\n        local p=g.members[s.crystalRoles[k]].pos\n        for j,q in ipairs(spots) do if not used[j] then\n            used[j]=true;pick[k]=j;solve(k+1,total+(p.x-q.x)^2+(p.z-q.z)^2);used[j]=nil\n        end end\n    end\n    solve(1,0);s.crystals={}\n    for k,i in ipairs(s.crystalRoles) do s.crystals[g.members[i].id]=spots[best[k]] end\n    d('[String TEA P3] inception crystal positions assigned count=4')\nend\nlocal p=s.crystals[player.id]\nif p then g.point(p.x,p.z) end\n\nself.used=true\n",
							name = "MuAi 八职能与机制分配",
							uuid = "d94892d7-6bb3-0b51-b6d5-7be39d109891",
							version = 2.1,
						},
