		{
			data = 
			{
				displayPath = "P3",
				name = "动态指路",
				uuid = "1e55a1a8-03de-cd9b-b081-1164d6384023",
			},
			objectType = "folder",
		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<635 or now>=665.4 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal g=data.stringTeaLateGuideV1\nif not g then\n    g={roles={'MT','ST','H1','H2','D1','D2','D3','D4'},members={},byID={}}\n    function g.buff(e,id)\n        local b=TensorCore.getBuff(e,id)\n        return b and b.duration and b.duration>0\n    end\n    function g.entity(cid,model)\n        local found\n        for _,e in pairs(TensorCore.entityList('contentid='..cid)) do\n            if e.pos and Argus.getEntityModel(e.id)==model then\n                if found then return end\n                found=e\n            end\n        end\n        return found\n    end\n    function g.point(x,z)\n        if type(x)~='number' or type(z)~='number' or x~=x or z~=z then return end\n        if (x-100)^2+(z-100)^2>19.7^2 then return end\n        m.FrameDirect(x,z,0.6)\n    end\n    data.stringTeaLateGuideV1=g\nend\nfor id in pairs(g.byID) do g.byID[id]=nil end\nlocal me\nfor i,r in ipairs(g.roles) do\n    local p=m.Party[r]\n    if not p or not p.id or g.byID[p.id] then return end\n    local e=TensorCore.mGetEntity(p.id)\n    if not e or not e.pos then return end\n    g.members[i],g.byID[p.id]=e,i\n    if p.id==player.id then me=i end\nend\nif not me then return end\nlocal e=g.members[me]\nlocal numbers=data.stringTeaLc2Preview\nlocal s=g.wormhole\nif not s then\n    if now>=649.5 then return end\n    local alex=g.entity(9220,11347);local bj=g.entity(9216,11340)\n    if not alex or not bj then return end\n    local dx,dz=alex.pos.x-100,alex.pos.z-100\n    local len=math.sqrt(dx*dx+dz*dz)\n    if len<18 or len>24 then return end\n    local ux,uz=dx/len,dz/len;local sx,sz=-uz,ux\n    if (bj.pos.x-100)*sx+(bj.pos.z-100)*sz<0 then sx,sz=-sx,-sz end\n    s={ux=ux,uz=uz,sx=sx,sz=sz,bx=bj.pos.x,bz=bj.pos.z};g.wormhole=s\nend\nif now<641 then\n    local dx,dz=100-s.bx,100-s.bz;local len=math.sqrt(dx*dx+dz*dz)\n    if len>1 then g.point(s.bx+3*dx/len,s.bz+3*dz/len) end\n    return\nend\nif not numbers or numbers.version~=1 or numbers.invalid or numbers.count~=8 then return end\nlocal n=numbers.seen[player.id]\nif not n or numbers.targets[n]~=player.id then return end\nlocal side=n%2==1 and 1 or -1\nlocal lateral,forward=side*19.2,0\nlocal soak\nif n<=2 then\n    -- #1 also baits the ray after #2's charge. Do not send it away at the charge.\n    if n==1 and now<649.7 then lateral,forward=8,-8\n    elseif now<(n==1 and 653.95 or 652.95) then lateral,forward=side*13.65,-13.65\n    elseif now<659.9 then lateral,forward=side*19.2,0\n    elseif now<664.2 then soak=3 else lateral,forward=side*19.2,0 end\nelseif n<=4 then\n    -- Fish #4: red-dot centre for Super Jump, then one step out to the wall.\n    if n==4 and now<651.05 then lateral,forward=-12.87,12.87\n    elseif now<656.95 then lateral,forward=side*13.65,13.65\n    else lateral,forward=side*19.2,0 end\nelseif n<=6 then\n    if n==5 and now<649.7 then lateral,forward=12,0\n    elseif now>=649.7 and now<655.85 then soak=1\n    elseif now>=655.85 and now<661.05 then lateral,forward=side*13.65,-13.65\n    elseif now>=661.05 then lateral,forward=side*19.2,0 end\nelse\n    -- #7 must wait inside the chakrams; #8 approaches on the opposite side.\n    if n==7 and now<649.7 then lateral,forward=12,0\n    elseif now>=655.85 and now<660.05 then soak=2\n    elseif now>=660.05 and now<665.35 then lateral,forward=side*13.65,13.65\n    elseif now>=665.35 then lateral,forward=side*19.2,0 end\nend\nif soak then\n    -- Either near/far arrangement: read both opposing helpers, never assume handedness.\n    local hx,hz,otherX,otherZ,count=nil,nil,nil,nil,0\n    for _,a in pairs(TensorCore.entityList('contentid=9220')) do\n        if a.pos and Argus.getEntityModel(a.id)==9020 then\n            local dx,dz=a.pos.x-100,a.pos.z-100\n            local l,f=dx*s.sx+dz*s.sz,dx*s.ux+dz*s.uz\n            if math.abs(math.abs(l)-11.08655)<0.35 and math.abs(math.abs(f)-4.5922)<0.35 then\n                count=count+1\n                if l*side>0 then hx,hz=a.pos.x,a.pos.z else otherX,otherZ=a.pos.x,a.pos.z end\n            end\n        end\n    end\n    if count~=2 or not hx or not otherX or (hx+otherX-200)^2+(hz+otherZ-200)^2>0.25 then return end\n    local out=soak==1 and 6.5 or soak==2 and 4.5 or 0\n    g.point(hx+side*out*s.sx,hz+side*out*s.sz)\nelse\n    g.point(100+lateral*s.sx+forward*s.ux,100+lateral*s.sz+forward*s.uz)\nend\n\nself.used=true\n",
							name = "MuAi 八职能与机制分配",
							uuid = "6427b5b2-2dfc-1741-99e1-21fd91c56254",
