							actionLua = "local now=TensorReactions_CurrentTimer\nif now<650 or now>=658.45 or eventArgs.entityContentID~=9216 then self.used=true;return end\nlocal spell=eventArgs.spellID\nif spell~=18506 and spell~=18507 and spell~=18508 then self.used=true;return end\nlocal caster=TensorCore.mGetEntity(eventArgs.entityID)\nlocal model=caster and Argus.getEntityModel(caster.id)\nif not caster or not caster.pos or (spell==18508 and model~=9020) or (spell~=18508 and model~=11340) then self.used=true;return end\nlocal s=data.stringTeaWormholeRayV1\nif spell==18506 then\n    if s then self.used=true;return end\n    local x,z=eventArgs.castPosX,eventArgs.castPosZ\n    if type(x)~='number' or type(z)~='number' or (x-100)^2+(z-100)^2>21^2 then self.used=true;return end\n    s={version=1,x=x,y=0,z=z,jumpAt=now,bossID=caster.id}\n    data.stringTeaWormholeRayV1=s\nelseif not s then\n    -- A late save can still show the remaining ray, but cannot reconstruct the jump preview.\n    s={version=1,x=caster.pos.x,y=0,z=caster.pos.z,bossID=caster.id}\n    data.stringTeaWormholeRayV1=s\nend\nif not s.drawer then\n    s.drawer=TensorCore.getMoogleDrawer()\n    s.roles={'MT','ST','H1','H2','D1','D2','D3','D4'}\n    s.seen={}\n    function s.farthest(v)\n        local m=MuAiGuide\n        if not m or type(m.Party)~='table' then return end\n        for id in pairs(v.seen) do v.seen[id]=nil end\n        local best,bestDist\n        for _,role in ipairs(v.roles) do\n            local p=m.Party[role]\n            if not p or not p.id or v.seen[p.id] then return end\n            v.seen[p.id]=true\n            local e=TensorCore.mGetEntity(p.id)\n            if not e or not e.pos then return end\n            if e.alive then\n                local dist=(e.pos.x-v.x)^2+(e.pos.z-v.z)^2\n                if not bestDist or dist>bestDist then best,bestDist=e,dist end\n            end\n        end\n        if not best or bestDist<1 then return end\n        return math.atan2(best.pos.x-v.x,best.pos.z-v.z),best.id\n    end\n    function s.render(v,t)\n        if not v.heading or t>=658.45 then return end\n        if v.uuid then\n            return v.drawer:updateTimedCone(v.uuid,nil,v.x,v.y,v.z,nil,nil,v.heading,nil,nil,nil,0)\n        end\n        v.uuid=v.drawer:addTimedCone((658.45-t)*1000,v.x,v.y,v.z,25.5,math.pi/2,v.heading,0,false,false,0)\n        return v.uuid~=nil\n    end\nend\nif spell==18508 then\n    s.x,s.z=caster.pos.x,caster.pos.z\n    s.heading=eventArgs.heading\n    s.locked=true;s.actual=true;s.actualAt=now\nelseif spell==18507 then\n    local heading,target=s.farthest(s)\n    if heading then\n        s.heading,s.targetID=heading,target\n        s.locked=true;s.lockedAt=now\n    end\nelseif not s.locked then\n    s.heading,s.targetID=s.farthest(s)\nend\ns.render(s,now)\nself.used=true\n",
