				eventType = 13,
				execute = "-- TEA LC2: predict 2 yalms behind odd player, then use the real landing point.\n-- 18484 cone R30/full 90 deg; 18883 charge L55/full width10.\nlocal t = TensorReactions_CurrentTimer\nif t < 652.2 or t >= 656.7 then return end\nlocal s = data.stringTeaLc2Preview\nif not s or s.version ~= 1 or s.invalid or s.count ~= 8 then return end\nlocal odd = TensorCore.mGetEntity(s.targets[3])\nlocal even = TensorCore.mGetEntity(s.targets[4])\nif not odd or not even or not odd.alive or not even.alive or not odd.pos or not even.pos then\n    return\nend\nlocal state = s.pair3\nif not state then\n    state = { origin = { x = 0, y = 0, z = 0 } }\n    s.pair3 = state\nend\nlocal p, origin = odd.pos, state.origin\nif not state.landed then\n    origin.x, origin.y, origin.z = p.x - 2 * math.sin(p.h), 0, p.z - 2 * math.cos(p.h)\n    if t >= 653.8 then\n        local source\n        for _, e in pairs(TensorCore.entityList(\"contentid=9218\")) do\n            if Argus.getEntityModel(e.id) == 11342 and Argus.isEntityVisible(e.id) then\n                if source then return end\n                source = e\n            end\n        end\n        if source and source.pos then\n            origin.x, origin.y, origin.z = source.pos.x, source.pos.y, source.pos.z\n            state.landed = true\n        end\n    end\nend\nlocal drawer = TensorCore.getMoogleDrawer()\nif t < 655.2 then\n    drawer:addCone(origin.x, origin.y, origin.z, 30, math.pi / 2, TensorCore.getHeadingToTarget(origin, p))\nend\ndrawer:addRect(origin.x, origin.y, origin.z, 55, 10, TensorCore.getHeadingToTarget(origin, even.pos))\nif not state.reported then\n    d(string.format(\"[String TEA LC2 frame] pair=3-4 count=%d odd=%d even=%d\", s.count, odd.id, even.id))\n    state.reported = true\nend",
