		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local s=data.stringTeaLateEnum\nif not s or s.version~=1 then self.used=true;return end\nlocal roles={'MT','ST','H1','H2','D1','D2','D3','D4'}\nlocal role\nfor i,r in ipairs(roles) do local p=MuAiGuide and MuAiGuide.Party[r];if p and p.id==eventArgs.entityID then role=i end end\nif not role then self.used=true;return end\nlocal before=s.count\nif eventArgs.markerID==65 then\n    if role<5 then s.invalid=true\n    elseif not s.enums[role] then s.enums[role]=eventArgs.entityID;s.count=s.count+1 end\nelseif eventArgs.markerID==67 then\n    if role>2 or s.ice and s.ice~=role then s.invalid=true else s.ice=role end\nend\nif s.count>2 then s.invalid=true end\nd(string.format('[String TEA P3] missile marker=%d role=%s count=%d->%d ice=%s invalid=%s',eventArgs.markerID,roles[role],before,s.count,tostring(s.ice),tostring(s.invalid)))\nself.used=true\n",
