		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local s=data.stringTeaLateOptical1\nif not s or s.invalid then self.used=true;return end\nlocal marker=eventArgs.markerID\nif marker~=62 and marker~=139 then self.used=true;return end\nlocal role\nfor i,r in ipairs({'MT','ST','H1','H2','D1','D2','D3','D4'}) do\n    local p=MuAiGuide and MuAiGuide.Party and MuAiGuide.Party[r]\n    if p and p.id==eventArgs.entityID then role=i end\nend\nif not role then self.used=true;return end\nlocal before=s.count\nif s.marker and s.marker~=marker then s.invalid=true end\ns.marker=marker\nif not s.targets[role] then s.targets[role]=true;s.count=s.count+1 end\nif s.count>(marker==62 and 2 or 8) then s.invalid=true end\nd(string.format('[String TEA optical] stringTeaLateOptical1 marker=%d count=%d->%d',marker,before,s.count))\nself.used=true\n",
							conditions = 
							{
								
								{
									"5064af7a-088c-2904-9dbe-dacef0d68694",
