					{
						data = 
						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<978 or now>=993.8 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal g=data.stringTeaLateGuideV1\nif not g then\n    g={roles={'MT','ST','H1','H2','D1','D2','D3','D4'},members={},byID={}}\n    function g.buff(e,id)\n        local b=TensorCore.getBuff(e,id)\n        return b and b.duration and b.duration>0\n    end\n    function g.entity(cid,model)\n        local found\n        for _,e in pairs(TensorCore.entityList('contentid='..cid)) do\n            if e.pos and Argus.getEntityModel(e.id)==model then\n                if found then return end\n                found=e\n            end\n        end\n        return found\n    end\n    function g.point(x,z)\n        if type(x)~='number' or type(z)~='number' or x~=x or z~=z then return end\n        if (x-100)^2+(z-100)^2>19.7^2 then return end\n        m.FrameDirect(x,z,0.6)\n    end\n    data.stringTeaLateGuideV1=g\nend\nfor id in pairs(g.byID) do g.byID[id]=nil end\nlocal me\nfor i,r in ipairs(g.roles) do\n    local p=m.Party[r]\n    if not p or not p.id or g.byID[p.id] then return end\n    local e=TensorCore.mGetEntity(p.id)\n    if not e or not e.pos then return end\n    g.members[i],g.byID[p.id]=e,i\n    if p.id==player.id then me=i end\nend\nif not me then return end\nlocal e=g.members[me]\nlocal s=data.stringTeaLateAlpha\nif not s or s.invalid or not s.big or not s.stack then return end\nif data.stringTeaStillStop and not data.stringTeaStillStop.resolved then return end\nlocal count,heavy=0,0\nfor _ in pairs(s.cross) do count=count+1 end\nfor _ in pairs(s.heavy) do heavy=heavy+1 end\nif count~=3 or heavy~=3 or s.heavy[s.big] or s.heavy[s.stack] or s.big==s.stack then return end\nif not s.points then\n    local safe,n=nil,0\n    for _,a in pairs(TensorCore.entityList('contentid=9042')) do\n        if a.pos and Argus.getEntityModel(a.id)==11349 and (a.pos.x-100)^2+(a.pos.z-100)^2>100 then\n            n=n+1\n            if not s.cross[a.id] then if safe then return end;safe=a end\n        end\n    end\n    if n~=4 or not safe then return end\n    local dx,dz=safe.pos.x-100,safe.pos.z-100\n    local len=math.sqrt(dx*dx+dz*dz);local ux,uz=dx/len,dz/len\n    local pts={big={x=100+15.5*ux,z=100+15.5*uz},heavy={x=100-18*ux+3*uz,z=100-18*uz-3*ux},stack={x=100-18*ux-3*uz,z=100-18*uz+3*ux}}\n    for _,p in pairs(pts) do\n        for _,c in pairs(s.cross) do\n            local x,z=p.x-c.x,p.z-c.z\n            if math.abs(x*math.sin(c.h)+z*math.cos(c.h))<=8.3 or math.abs(x*math.cos(c.h)-z*math.sin(c.h))<=8.3 then return end\n        end\n    end\n    s.points=pts\n    d('[String TEA Alpha] complete points solved: big=1 heavy=3 stack=4 cross=3')\nend\nlocal p=player.id==s.big and s.points.big or s.heavy[player.id] and s.points.heavy or s.points.stack\ng.point(p.x,p.z)\n\nself.used=true\n",
