							actionLua = "local now=TensorReactions_CurrentTimer\nif now<1063 or now>=1073.3 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal g=data.stringTeaLateGuideV1\nif not g then\n    g={roles={'MT','ST','H1','H2','D1','D2','D3','D4'},members={},byID={}}\n    function g.buff(e,id)\n        local b=TensorCore.getBuff(e,id)\n        return b and b.duration and b.duration>0\n    end\n    function g.entity(cid,model)\n        local found\n        for _,e in pairs(TensorCore.entityList('contentid='..cid)) do\n            if e.pos and Argus.getEntityModel(e.id)==model then\n                if found then return end\n                found=e\n            end\n        end\n        return found\n    end\n    function g.point(x,z)\n        if type(x)~='number' or type(z)~='number' or x~=x or z~=z then return end\n        if (x-100)^2+(z-100)^2>19.7^2 then return end\n        m.FrameDirect(x,z,0.6)\n    end\n    data.stringTeaLateGuideV1=g\nend\nfor id in pairs(g.byID) do g.byID[id]=nil end\nlocal me\nfor i,r in ipairs(g.roles) do\n    local p=m.Party[r]\n    if not p or not p.id or g.byID[p.id] then return end\n    local e=TensorCore.mGetEntity(p.id)\n    if not e or not e.pos then return end\n    g.members[i],g.byID[p.id]=e,i\n    if p.id==player.id then me=i end\nend\nif not me then return end\nlocal e=g.members[me]\nlocal s=data.stringTeaLateBeta\nif not s or s.invalid then return end\nif now<1073.3 then\n    if not s.colors or not s.near or not s.far or not s.stack then return end\n    local count,light,dark=0,nil,nil\n    for id in pairs(s.beacons) do\n        count=count+1\n        if s.colors[id]==1 then light=id elseif s.colors[id]==2 then dark=id end\n    end\n    if count~=2 or not light or not dark or s.colors[s.stack]~=1 then return end\n    local l,d=TensorCore.mGetEntity(light),TensorCore.mGetEntity(dark)\n    if not l or not d or not l.alive or not d.alive or not l.pos or not d.pos then return end\n    local function dist2(a,b)return (a.x-b.x)^2+(a.z-b.z)^2 end\n    local function inside(p,r)return (p.x-100)^2+(p.z-100)^2<r*r end\n    local lp,dp=l.pos,d.pos\n    -- Beacons establish the guide's north/east arrangement, then retain their\n    -- actual valid location. Followers always use actual beacon coordinates.\n    if player.id==light then\n        if lp.z<85 and math.abs(lp.x-100)<5 and inside(lp,19.5) and dist2(lp,dp)>25.5^2 then g.point(lp.x,lp.z)\n        else g.point(100,81) end\n        return\n    elseif player.id==dark then\n        if dp.x>116 and math.abs(dp.z-100)<4 and inside(dp,19.5) and dist2(lp,dp)>25.5^2 then g.point(dp.x,dp.z)\n        else g.point(119,100) end\n        return\n    end\n    local dx,dz=lp.x-dp.x,lp.z-dp.z\n    local length=math.sqrt(dx*dx+dz*dz)\n    if length<25.5 then return end\n    -- A shared point 2m from actual dark, toward actual light. Both forced\n    -- movements are parallel here, keeping the light stack and near pair close.\n    local ux,uz=dx/length,dz/length\n    local radius=2\n    local common={x=dp.x+radius*ux,z=dp.z+radius*uz}\n    if not inside(common,19.3) or dist2(common,lp)<22.5^2 then return end\n    if s.colors[player.id]==1 then\n        g.point(common.x,common.z)\n        return\n    end\n    if s.colors[player.id]~=2 then return end\n    if not s.near[player.id] and not s.far[player.id] then\n        local ix,iz=100-dp.x,100-dp.z\n        local len=math.sqrt(ix*ix+iz*iz)\n        if len<1 then return end\n        ix,iz=ix/len,iz/len\n        local p={x=dp.x+radius*ix,z=dp.z+radius*iz}\n        if inside({x=p.x+20*ix,z=p.z+20*iz},19.1) then g.point(p.x,p.z) end\n        return\n    end\n    -- Exactly one opposite-color partner for each recorded tether.\n    local pair=s.near[player.id] and s.near or s.far\n    local partner,number=nil,0\n    for id in pairs(pair) do\n        number=number+1\n        if id~=player.id then partner=TensorCore.mGetEntity(id) end\n    end\n    if number~=2 or not partner or not partner.alive or not partner.pos or s.colors[partner.id]~=1 then return end\n    local near=s.near[player.id]\n    -- Before the light partner reaches the shared point, use the planned\n    -- meeting point for provisional directions; actual feet refine it nearby.\n    local peerStart=dist2(partner.pos,common)<=.75^2 and partner.pos or common\n    local px,pz=lp.x-peerStart.x,lp.z-peerStart.z\n    local plen=math.sqrt(px*px+pz*pz)\n    if plen<22.5 then return end\n    px,pz=px/plen,pz/plen\n    local best,bestScore\n    -- Check an 18-20m movement envelope, not just a single guessed endpoint.\n    -- All three dark positions retain the user-requested 2m radius.\n    local inward=math.atan2(100-dp.z,100-dp.x)\n    for step=-75,75 do\n        local a=inward+step*math.pi/180\n        local vx,vz=math.cos(a),math.sin(a)\n        if (near and vz<0) or (not near and vz>0) then\n            local p={x=dp.x+radius*vx,z=dp.z+radius*vz}\n            local safe=inside(p,19.3)\n            local worst=near and 0 or math.huge\n            for _,dm in ipairs({18,20}) do\n                local destination={x=p.x+dm*vx,z=p.z+dm*vz}\n                if not inside(destination,19.1) then safe=false end\n                for _,lm in ipairs({18,20}) do\n                    local peer={x=peerStart.x+lm*px,z=peerStart.z+lm*pz}\n                    local d2=dist2(destination,peer)\n                    if near then worst=math.max(worst,d2) else worst=math.min(worst,d2) end\n                end\n            end\n            if near and worst>4.2^2 then safe=false end\n            if not near then\n                local finish={x=p.x+20*vx,z=p.z+20*vz}\n                local peer={x=peerStart.x+20*px,z=peerStart.z+20*pz}\n                if dist2(finish,peer)<30.8^2 then safe=false end\n            end\n            if safe then\n                local preferred=near and dist2(p,common) or (step+45)^2*.001\n                local score=(near and worst or -worst*.05)+preferred*.2\n                if not bestScore or score<bestScore then best,bestScore=p,score end\n            end\n        end\n    end\n    if best then g.point(best.x,best.z) end\nelseif now>=1082.7 and now<1088.6 then\n    -- Spread has no assigned position; leave movement to the player.\n    if s.optical~='stack' or not s.colors then return end\n    local counts={0,0}\n    for _,member in ipairs(g.members) do\n        local color=s.colors[member.id]\n        if color~=1 and color~=2 then return end\n        counts[color]=counts[color]+1\n    end\n    if counts[1]~=4 or counts[2]~=4 then return end\n    -- Light group north, dark group south, regardless of role or beacon feet.\n    g.point(100,s.colors[player.id]==1 and 94 or 106)\nelseif now>=1088.7 and s.donut then\n    local a=TensorCore.mGetEntity(s.donut)\n    if a and a.pos then\n        local dx,dz=100-a.pos.x,100-a.pos.z;local len=math.sqrt(dx*dx+dz*dz)\n        if len>0 then g.point(a.pos.x+3*dx/len,a.pos.z+3*dz/len) end\n    end\nend\n\nself.used=true\n",
