				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now>=1136 then self.used=true;return end\nlocal points,seen={},{}\nfor _,a in ipairs(Argus.getCurrentAOEs()) do\n    if a.aoeID==18575 and a.contentID==9042 and not a.friendly and a.x and a.z then\n        local key=string.format('%.1f:%.1f',a.x,a.z)\n        if not seen[key] then seen[key]=true;points[#points+1]={x=a.x,z=a.z} end\n    end\nend\nif #points<8 or #points>9 then self.candidate=nil;return end\nlocal s=data.stringTeaLateJudgment1\nif not s then s={waves={}};data.stringTeaLateJudgment1=s end\nlocal keys={};for key in pairs(seen) do keys[#keys+1]=key end;table.sort(keys)\nlocal signature=table.concat(keys,';')\nif not self.candidate or self.candidate.signature~=signature then\n    self.candidate={signature=signature,time=now,points=points};return\nend\nif now-self.candidate.time<0.1 then return end\nif s.lastSignature==signature then return end\nlocal all={};for _,wave in ipairs(s.waves) do for _,p in ipairs(wave) do all[string.format('%.1f:%.1f',p.x,p.z)]=true end end\nfor key in pairs(seen) do if all[key] then return end end\nif #s.waves>=3 then return end\nif #s.waves==0 then s.firstAt=self.candidate.time end\ns.waves[#s.waves+1]=points;s.lastSignature=signature\nd('[String TEA judgment] stringTeaLateJudgment1 wave='..#s.waves..' count='..#points)\nif #s.waves==3 then\n    local count=0;for key in pairs(seen) do all[key]=true end;for _ in pairs(all) do count=count+1 end\n    s.ready=count==25\n    self.used=true\nend\n",
