						{
							category = "Lua",
							conditionLua = "local now=TensorReactions_CurrentTimer\nif type(now)~='number' or now<1139.8 or now>=1142.1 then return false end\n-- Never submit a new action while the existing stop controller owns the player.\nif data.stringTeaStillStop then return false end\nlocal p=TensorCore.mGetPlayer()\nif not p or not p.alive or not p.pos then return false end\nlocal jobs={[20]=true,[22]=true,[30]=true,[34]=true,[39]=true,[41]=true}\nif not jobs[p.job] then return false end\nif TensorCore.getBuff(p,1119) then return false end\nfor _,boss in pairs(TensorCore.entityList('contentid=9042')) do\n    local c=boss.castinginfo\n    if c and c.castingid==18559 and c.casttime and c.channeltime and c.channeltime<c.casttime then return false end\nend\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' then return false end\nlocal members,seen,me={},{},nil\nfor i,role in ipairs({'MT','ST','H1','H2','D1','D2','D3','D4'}) do\n    local member=m.Party[role]\n    if not member or not member.id or seen[member.id] then return false end\n    local e=TensorCore.mGetEntity(member.id)\n    if not e or not e.pos or not e.job then return false end\n    members[i],seen[member.id]=e,true\n    if e.id==p.id then me=i end\nend\nif not me or me<5 then return false end\nlocal eligible={}\nfor _,i in ipairs({5,6,7,8}) do if jobs[members[i].job] then eligible[#eligible+1]=i end end\nlocal owner=({[2]=2,[3]=2,[4]=2})[#eligible]\nif not owner or eligible[owner]~=me then return false end\nlocal function dist2(a,b) return (a.pos.x-b.pos.x)^2+(a.pos.z-b.pos.z)^2 end\n\n\nreturn true\n",
