		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local now=TensorReactions_CurrentTimer\nif now<1168 or now>=1187.1 then return end\nlocal m=MuAiGuide\nif not m or type(m.Party)~='table' or type(m.GetPlayer)~='function' or type(m.FrameDirect)~='function' then return end\nlocal player=m.GetPlayer()\nif not player then return end\nlocal g=data.stringTeaLateGuideV1\nif not g then\n    g={roles={'MT','ST','H1','H2','D1','D2','D3','D4'},members={},byID={}}\n    function g.buff(e,id)\n        local b=TensorCore.getBuff(e,id)\n        return b and b.duration and b.duration>0\n    end\n    function g.entity(cid,model)\n        local found\n        for _,e in pairs(TensorCore.entityList('contentid='..cid)) do\n            if e.pos and Argus.getEntityModel(e.id)==model then\n                if found then return end\n                found=e\n            end\n        end\n        return found\n    end\n    function g.point(x,z)\n        if type(x)~='number' or type(z)~='number' or x~=x or z~=z then return end\n        if (x-100)^2+(z-100)^2>19.7^2 then return end\n        m.FrameDirect(x,z,0.6)\n    end\n    data.stringTeaLateGuideV1=g\nend\nfor id in pairs(g.byID) do g.byID[id]=nil end\nlocal me\nfor i,r in ipairs(g.roles) do\n    local p=m.Party[r]\n    if not p or not p.id or g.byID[p.id] then return end\n    local e=TensorCore.mGetEntity(p.id)\n    if not e or not e.pos then return end\n    g.members[i],g.byID[p.id]=e,i\n    if p.id==player.id then me=i end\nend\nif not me then return end\nlocal e=g.members[me]\nlocal s=data.stringTeaLateJudgment2\nif not s or not s.firstAt or not s.waves or #s.waves<2 or now>=s.firstAt+12.2 then return end\n-- Two complete disjoint previews determine the third of 25 grid locations.\nlocal waves,seen={{},{}},{}\nlocal function key(x,z)return x..':'..z end\nfor i=1,2 do\n    local source=s.waves[i]\n    if #source~=8 and #source~=9 then return end\n    for _,p in ipairs(source) do\n        local x=84+8*math.floor((p.x-84)/8+.5)\n        local z=84+8*math.floor((p.z-84)/8+.5)\n        if x<84 or x>116 or z<84 or z>116 or math.abs(x-p.x)>.25 or math.abs(z-p.z)>.25 then return end\n        local k=key(x,z)\n        if seen[k] then return end\n        seen[k]=i;waves[i][#waves[i]+1]={x=x,z=z}\n    end\nend\nwaves[3]={}\nfor x=84,116,8 do for z=84,116,8 do\n    if not seen[key(x,z)] then waves[3][#waves[3]+1]={x=x,z=z};seen[key(x,z)]=3 end\nend end\nif #waves[3]~=8 and #waves[3]~=9 then return end\nif s.waves[3] then\n    if #s.waves[3]~=#waves[3] then return end\n    local verified={}\n    for _,p in ipairs(s.waves[3]) do\n        local x=84+8*math.floor((p.x-84)/8+.5)\n        local z=84+8*math.floor((p.z-84)/8+.5)\n        local k=key(x,z)\n        if math.abs(x-p.x)>.25 or math.abs(z-p.z)>.25 or seen[k]~=3 or verified[k] then return end\n        verified[k]=true\n    end\nend\n-- Fish 17:28-18:08: south/east inverted-L, not arbitrary arena points.\nlocal anchors={{x=100,z=108},{x=108,z=108},{x=108,z=100}}\nlocal firstAnchor,lastAnchor,labels=nil,nil,{}\nfor _,p in ipairs(anchors) do\n    local wave=seen[key(p.x,p.z)]\n    if labels[wave] then return end\n    labels[wave]=true\n    if wave==3 then firstAnchor=p elseif wave==1 then lastAnchor=p end\nend\nif not firstAnchor or not lastAnchor then return end\nif s.routeVersion~=2 then s.points=nil;s.path=nil;s.routeVersion=2 end\nif not s.points then\n    local function safe(p,a,b)\n        if (p.x-100)^2+(p.z-100)^2>19.2^2 then return false end\n        for _,wave in ipairs({a,b}) do for _,c in ipairs(wave) do\n            if (p.x-c.x)^2+(p.z-c.z)^2<6.5^2 then return false end\n        end end\n        return true\n    end\n    local bestScore,first,last\n    -- Offset near the selected regions only when a diagonal needs clearance.\n    for _,sx in ipairs({0,-1.5,1.5}) do for _,sz in ipairs({0,-1.5,1.5}) do\n        local p={x=firstAnchor.x+sx,z=firstAnchor.z+sz}\n        if safe(p,waves[1],waves[2]) then\n            for _,tx in ipairs({0,-1.5,1.5}) do for _,tz in ipairs({0,-1.5,1.5}) do\n                local q={x=lastAnchor.x+tx,z=lastAnchor.z+tz}\n                local dx,dz=q.x-p.x,q.z-p.z\n                local len2=dx*dx+dz*dz\n                local clear=len2>0 and len2<=12^2 and safe(q,waves[2],waves[3])\n                if clear then for _,c in ipairs(waves[2]) do\n                    local t=math.max(0,math.min(1,((c.x-p.x)*dx+(c.z-p.z)*dz)/len2))\n                    if (p.x+t*dx-c.x)^2+(p.z+t*dz-c.z)^2<6.5^2 then clear=false;break end\n                end end\n                if clear then\n                    local score=sx*sx+sz*sz+tx*tx+tz*tz+len2*.01\n                    if not bestScore or score<bestScore then bestScore,first,last=score,p,q end\n                end\n            end end\n        end\n    end end\n    if not first then return end\n    s.points={first};s.path={last};s.progress={}\nend\nlocal p=now>=s.firstAt+8.15 and s.path[1] or s.points[1]\ng.point(p.x,p.z)\n\nself.used=true\n",
